class MonthlyPlan implements Chargeable, Discountable {
    @Override
    public double baseFee() {
        return 1500.00;
    }

    @Override
    public double planDiscount() {
        return 0.0;
    }
}

class QuarterlyPlan implements Chargeable, Discountable {
    @Override
    public double baseFee() {
        return 4200.00;
    }

    @Override
    public double planDiscount() {
        return 4200.00 * 0.05; // 5% of base fee = 210.00
    }
}

class AnnualPlan implements Chargeable, Discountable {
    @Override
    public double baseFee() {
        return 15000.00;
    }

    @Override
    public double planDiscount() {
        return 15000.00 * 0.12; // 12% of base fee = 1800.00
    }
}
